def comparison_table(topic):
    rows = [
        ("GRAI Licence", "Active GRAI-RB licence, verifiable at grai.ie", f"Legal protection for Irish {topic} bettors"),
        ("Odds Quality", "Low overround (&lt;5% on major markets)", "Better value on every bet you place"),
        ("Market Depth", f"Wide range of {topic} markets", "More opportunities and bet types available"),
        ("Live Betting", "Fast in-play odds with minimal delays", "Bet as the action unfolds"),
        ("Payment Methods", "Revolut, debit card, Apple Pay, Google Pay", "Fast deposits and withdrawals in Ireland"),
        ("Responsible Gambling", "Deposit limits, self-exclusion, GAT links", "GRAI-required safeguards for all customers"),
    ]
    html = """<div class="comparison-table" style="overflow-x:auto;margin:24px 0">
  <table>
    <thead><tr><th>Feature</th><th>What to Look For</th><th>Why It Matters for TOPIC</th></tr></thead>
    <tbody>
ROWS
    </tbody>
  </table>
</div>""".replace("TOPIC", topic)
    row_html = "\n".join(
        f"      <tr><td><strong>{r[0]}</strong></td><td>{r[1]}</td><td>{r[2]}</td></tr>"
        for r in rows
    )
    return html.replace("ROWS", row_html)


def faq_schema(faqs):
    items = []
    for q, a in faqs:
        items.append(
            f'{{"@type":"Question","name":"{q}","acceptedAnswer":{{"@type":"Answer","text":"{a}"}}}}'
        )
    return (
        '<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":['
        + ",".join(items)
        + "]}</script>"
    )


def faq_html(faqs):
    items = []
    for q, a in faqs:
        items.append(
            f'<div class="faq-item"><div class="faq-question">{q}</div>'
            f'<div class="faq-answer"><p>{a}</p></div></div>'
        )
    return "<h2>Frequently Asked Questions</h2>\n" + "\n".join(items)


