def main():
    written = []
    skipped = []

    for page in PAGES:
        slug = page["slug"]
        out_path = os.path.join(PAGES_DIR, f"{slug}.html")
        if os.path.exists(out_path):
            skipped.append(slug)
            continue
        html = build_page(page)
        with open(out_path, "w", encoding="utf-8") as f:
            f.write(html)
        written.append(slug)

    print(f"Written : {len(written)}")
    print(f"Skipped : {len(skipped)}")
    for s in written:
        print(f"  + {s}")
    for s in skipped:
        print(f"  ~ {s} (already exists)")


if __name__ == "__main__":
    main()
